UPDATE abt_variabel SET nama = 'CIRI PERKARA SAMPUL (OTOMATIS: gabungan 5802 sampai 5827 tanpa 5804; kosong semua = tidak ada ciri khusus)', data_type = 'data_sql', sql_query = 'SELECT IFNULL(NULLIF(TRIM(CONCAT_WS(''  '',NULLIF(''#5802#'',''''),NULLIF(''#5803#'',''''),NULLIF(''#5805#'',''''),NULLIF(''#5806#'',''''),NULLIF(''#5807#'',''''),NULLIF(''#5808#'',''''),NULLIF(''#5809#'',''''),NULLIF(''#5810#'',''''),NULLIF(''#5811#'',''''),NULLIF(''#5812#'',''''),NULLIF(''#5813#'',''''),NULLIF(''#5814#'',''''),NULLIF(''#5815#'',''''),NULLIF(''#5816#'',''''),NULLIF(''#5817#'',''''),NULLIF(''#5818#'',''''),NULLIF(''#5819#'',''''),NULLIF(''#5820#'',''''),NULLIF(''#5821#'',''''),NULLIF(''#5822#'',''''),NULLIF(''#5823#'',''''),NULLIF(''#5824#'',''''),NULLIF(''#5825#'',''''),NULLIF(''#5826#'',''''),NULLIF(''#5827#'',''''))),''''),''- tidak ada ciri khusus -'') AS data', locked = 1 WHERE no_var = 5801 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '94ab54621be77ab2e58c1c6a07d8f383';
UPDATE abt_variabel SET nama = 'BARIS IKRAR TALAK SAMPUL (OTOMATIS; kosong bila bukan cerai talak)', data_type = 'data_sql', sql_query = 'SELECT IFNULL((SELECT CONCAT(''<b>IKRAR TALAK</b>  PMH '',IFNULL(CONCAT(DAY(i.penetapan_majelis_hakim),'' '',ELT(MONTH(i.penetapan_majelis_hakim),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.penetapan_majelis_hakim)),''-''),''  -  PHS ikrar '',IFNULL(CONCAT(DAY(i.tanggal_penetapan_sidang_ikrar),'' '',ELT(MONTH(i.tanggal_penetapan_sidang_ikrar),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.tanggal_penetapan_sidang_ikrar)),''-''),''  -  Sidang ikrar '',IFNULL(CONCAT(DAY(i.tgl_ikrar_talak),'' '',ELT(MONTH(i.tgl_ikrar_talak),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.tgl_ikrar_talak)),''-'')) FROM perkara_ikrar_talak i WHERE i.perkara_id=#perkara_id# LIMIT 1),'''') AS data', locked = 1 WHERE no_var = 5829 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '0c167c5f7a6bd8c6ccaaac49a40528e1';
UPDATE abt_variabel SET nama = 'CIRI PERKARA AWAL SAMPUL (OTOMATIS: ciri yang berlaku dan sudah diketahui saat daftar; tanpa ghaib, mafqud, verstek, rekonvensi, mediasi, sita)', data_type = 'data_sql', sql_query = 'SELECT IFNULL(NULLIF(TRIM(CONCAT_WS(''  '',NULLIF(''#5802#'',''''),NULLIF(''#5803#'',''''),NULLIF(''#5805#'',''''),NULLIF(''#5806#'',''''),NULLIF(''#5809#'',''''),NULLIF(''#5810#'',''''),NULLIF(''#5811#'',''''),NULLIF(''#5812#'',''''),NULLIF(''#5813#'',''''),NULLIF(''#5814#'',''''),NULLIF(''#5815#'',''''),NULLIF(''#5816#'',''''),NULLIF(''#5822#'',''''),NULLIF(''#5823#'',''''),NULLIF(''#5824#'',''''),NULLIF(''#5825#'',''''),NULLIF(''#5826#'',''''),NULLIF(''#5827#'',''''))),''''),''- tidak ada ciri khusus -'') AS data', locked = 1 WHERE no_var = 5861 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = 'ae3b8f63f2900312023cef946185cde4';
UPDATE abt_variabel SET nama = 'TURUT TERGUGAT SAMPUL (tiga nama sebaris; lebihnya "dan N lainnya" ke lampiran; kosong bila tidak ada)', data_type = 'data_sql', sql_query = 'SELECT CONCAT(''TURUT TERGUGAT ('',COUNT(*),'')  '',GROUP_CONCAT(CASE WHEN a.urutan<=3 THEN CONCAT(ELT(a.urutan,''I'',''II'',''III'',''IV'',''V'',''VI'',''VII'',''VIII'',''IX'',''X'',''XI'',''XII'',''XIII'',''XIV'',''XV'',''XVI'',''XVII'',''XVIII'',''XIX'',''XX''),''. '',a.nama) END ORDER BY a.urutan SEPARATOR ''  -  ''),IF(COUNT(*)>3,CONCAT(''  -  dan '',COUNT(*)-3,'' lainnya (lampiran)''),'''')) AS data FROM perkara_pihak4 a WHERE a.perkara_id=#perkara_id# HAVING COUNT(*)>0', locked = 1 WHERE no_var = 5897 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '7317dc4788dffbb21af6f0b7cf7b4f12';
UPDATE abt_variabel SET nama = 'PEKERJAAN DAN ALAMAT PIHAK I SAMPUL AWAL (langsung dari SIPP)', data_type = 'data_sql', sql_query = 'SELECT CONCAT(''Pekerjaan: '',IFNULL(NULLIF(h.pekerjaan,''''),''-''),''  -  Alamat: '',IFNULL(a.alamat,'''')) AS data FROM perkara_pihak1 a LEFT JOIN pihak h ON h.id=a.pihak_id WHERE a.perkara_id=#perkara_id# ORDER BY a.urutan LIMIT 1', locked = 1 WHERE no_var = 5830 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = 'bc122a2457a0d339c68d779ab37dd0ba';
UPDATE abt_variabel SET nama = 'PEKERJAAN DAN ALAMAT PIHAK II SAMPUL AWAL (langsung dari SIPP)', data_type = 'data_sql', sql_query = 'SELECT CONCAT(''Pekerjaan: '',IFNULL(NULLIF(h.pekerjaan,''''),''-''),''  -  Alamat: '',IFNULL(a.alamat,'''')) AS data FROM perkara_pihak2 a LEFT JOIN pihak h ON h.id=a.pihak_id WHERE a.perkara_id=#perkara_id# ORDER BY a.urutan LIMIT 1', locked = 1 WHERE no_var = 5831 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '36e0d98c88936d06c7cc6395a321b438';
UPDATE abt_variabel SET nama = 'INTERVENSI SAMPUL AWAL (OTOMATIS: pihak intervensi dari SIPP, tiga nama sebaris; kosong bila tidak ada)', data_type = 'data_sql', sql_query = 'SELECT CONCAT(''INTERVENSI ('',COUNT(*),'')  '',GROUP_CONCAT(CASE WHEN a.urutan<=3 THEN CONCAT(ELT(a.urutan,''I'',''II'',''III'',''IV'',''V'',''VI'',''VII'',''VIII'',''IX'',''X'',''XI'',''XII'',''XIII'',''XIV'',''XV'',''XVI'',''XVII'',''XVIII'',''XIX'',''XX''),''. '',a.nama) END ORDER BY a.urutan SEPARATOR ''  -  ''),IF(COUNT(*)>3,CONCAT(''  -  dan '',COUNT(*)-3,'' lainnya (lampiran)''),'''')) AS data FROM perkara_pihak3 a WHERE a.perkara_id=#perkara_id# HAVING COUNT(*)>0', locked = 1 WHERE no_var = 5847 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '107e57ab8fb1b0658ea26394ccb2e7b1';
COMMIT;
